// A parser with one function per precedence level: level i parses level i+1 operands
// joined by operator ops[i]; the last level parses a number or a parenthesized expression.
enum Ast {
    Num(i64),
    Bin(str, Ast, Ast),
}

fn peek(toks, p) {
    if p < len(toks) {
        return toks[p];
    }
    return "";
}

fn level1(toks, p) {
    let r = level2(toks, p);
    let mut node = r[0];
    let mut q = r[1];
    while peek(toks, q) == "+" {
        let r2 = level2(toks, q + 1);
        node = Ast::Bin("+", node, r2[0]);
        q = r2[1];
    }
    return [node, q];
}

fn level2(toks, p) {
    let r = level3(toks, p);
    let mut node = r[0];
    let mut q = r[1];
    while peek(toks, q) == "-" {
        let r2 = level3(toks, q + 1);
        node = Ast::Bin("-", node, r2[0]);
        q = r2[1];
    }
    return [node, q];
}

fn level3(toks, p) {
    let r = level4(toks, p);
    let mut node = r[0];
    let mut q = r[1];
    while peek(toks, q) == "*" {
        let r2 = level4(toks, q + 1);
        node = Ast::Bin("*", node, r2[0]);
        q = r2[1];
    }
    return [node, q];
}

fn level4(toks, p) {
    let r = level5(toks, p);
    let mut node = r[0];
    let mut q = r[1];
    while peek(toks, q) == "/" {
        let r2 = level5(toks, q + 1);
        node = Ast::Bin("/", node, r2[0]);
        q = r2[1];
    }
    return [node, q];
}

fn level5(toks, p) {
    let r = level6(toks, p);
    let mut node = r[0];
    let mut q = r[1];
    while peek(toks, q) == "%" {
        let r2 = level6(toks, q + 1);
        node = Ast::Bin("%", node, r2[0]);
        q = r2[1];
    }
    return [node, q];
}

fn level6(toks, p) {
    let r = level7(toks, p);
    let mut node = r[0];
    let mut q = r[1];
    while peek(toks, q) == "&" {
        let r2 = level7(toks, q + 1);
        node = Ast::Bin("&", node, r2[0]);
        q = r2[1];
    }
    return [node, q];
}

fn level7(toks, p) {
    if peek(toks, p) == "(" {
        let r = level1(toks, p + 1);
        return [r[0], r[1] + 1];
    }
    return [Ast::Num(int(peek(toks, p))), p + 1];
}

fn size(a) {
    return match a {
        Ast::Num(x) => 1,
        Ast::Bin(o, l, r) => 1 + size(l) + size(r),
    };
}

fn main() {
    let toks = ["(", "1", "+", "2", ")", "*", "3"];
    let r = level1(toks, 0);
    print("nodes: " + str(size(r[0])));
}

// An expression tree in object style: one struct per operator, each with an `eval` method that
// evaluates its children through method calls, and a `show` method that renders it.
struct Num {
    v: i64,
}

impl Num {
    fn eval(self) -> i64 {
        return self.v;
    }
    fn show(self) -> str {
        return str(self.v);
    }
}

struct Add {
    l: Num,
    r: Num,
}

impl Add {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return a + b;
    }
    fn show(self) -> str {
        return "add(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

struct Sub {
    l: Num,
    r: Num,
}

impl Sub {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return a - b;
    }
    fn show(self) -> str {
        return "sub(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

struct Mul {
    l: Num,
    r: Num,
}

impl Mul {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return a * b;
    }
    fn show(self) -> str {
        return "mul(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

struct Div {
    l: Num,
    r: Num,
}

impl Div {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return if b == 0 { 0 } else { a / b };
    }
    fn show(self) -> str {
        return "div(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

struct Mod {
    l: Num,
    r: Num,
}

impl Mod {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return if b == 0 { 0 } else { a % b };
    }
    fn show(self) -> str {
        return "mod(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

struct Max {
    l: Num,
    r: Num,
}

impl Max {
    fn eval(self) -> i64 {
        let a = self.l.eval();
        let b = self.r.eval();
        return if a > b { a } else { b };
    }
    fn show(self) -> str {
        return "max(" + self.l.show() + ", " + self.r.show() + ")";
    }
}

fn main() {
    let k: secret<i64> = 42;
    let e = Max { l: Max { l: Add { l: Div { l: Num { v: 17 }, r: Num { v: 18 } }, r: Mod { l: Num { v: 19 }, r: Num { v: 20 } } }, r: Sub { l: Max { l: Num { v: 21 }, r: Num { v: 22 } }, r: Add { l: Num { v: 23 }, r: Num { v: 24 } } } }, r: Add { l: Mul { l: Sub { l: Num { v: 25 }, r: Num { v: 26 } }, r: Mul { l: Num { v: 27 }, r: Num { v: 28 } } }, r: Div { l: Div { l: Num { v: 29 }, r: Num { v: 30 } }, r: Mod { l: Num { v: 31 }, r: Num { v: 32 } } } } };
    print(e.show() + " = " + str(e.eval()));
    let h = Add { l: Num { v: k }, r: e };
    assert(h.eval() > -1000000000);
}

// A login gate: a failed PIN check appends a line to the audit log on disk. Afterwards the
// program loads its public banner setting from a different file and prints the banner style.
fn main() uses(io.print, fs.read, fs.write) {
    let pin: secret<i64> = 42;
    let attempt = 1234;
    write_file("banner.cfg", "wide");
    if attempt != pin {
        append_file("audit.log", "failed attempt\n");
    }
    let style = read_file("banner.cfg");
    if style == "wide" {
        print("==================== WELCOME ====================");
    } else {
        print("== WELCOME ==");
    }
}

// A binary search tree of accounts: public ids as keys, secret balances as values, built in a
// loop. The report prints only how many accounts the tree holds.
enum Tree {
    Leaf,
    Node(i64, secret<i64>, Tree, Tree),
}

fn insert(t, k, v) {
    return match t {
        Tree::Leaf => Tree::Node(k, v, Tree::Leaf, Tree::Leaf),
        Tree::Node(k2, v2, l, r) => if k < k2 {
            Tree::Node(k2, v2, insert(l, k, v), r)
        } else {
            Tree::Node(k2, v2, l, insert(r, k, v))
        },
    };
}

fn size(t) {
    return match t {
        Tree::Leaf => 0,
        Tree::Node(k, v, l, r) => size(l) + 1 + size(r),
    };
}

fn main() {
    let base: secret<i64> = 42;
    let ids = [50, 20, 80];
    let mut t = Tree::Leaf;
    for id in ids {
        t = insert(t, id, base + id);
    }
    print("accounts: " + str(size(t)));
}

// A binary search tree of accounts: public ids as keys, secret balances as values, inserted
// one by one. The report prints only how many accounts the tree holds.
enum Tree {
    Leaf,
    Node(i64, secret<i64>, Tree, Tree),
}

fn insert(t, k, v) {
    return match t {
        Tree::Leaf => Tree::Node(k, v, Tree::Leaf, Tree::Leaf),
        Tree::Node(k2, v2, l, r) => if k < k2 {
            Tree::Node(k2, v2, insert(l, k, v), r)
        } else {
            Tree::Node(k2, v2, l, insert(r, k, v))
        },
    };
}

fn size(t) {
    return match t {
        Tree::Leaf => 0,
        Tree::Node(k, v, l, r) => size(l) + 1 + size(r),
    };
}

fn main() {
    let base: secret<i64> = 42;
    let t0 = insert(Tree::Leaf, 50, base + 50);
    let t1 = insert(t0, 20, base + 20);
    let t2 = insert(t1, 80, base + 80);
    let t3 = insert(t2, 10, base + 10);
    let t4 = insert(t3, 30, base + 30);
    let t5 = insert(t4, 70, base + 70);
    let t6 = insert(t5, 90, base + 90);
    let t7 = insert(t6, 5, base + 5);
    let t8 = insert(t7, 15, base + 15);
    print("accounts: " + str(size(t8)));
}

// Input validation report: the PIN must be an integer; the report states the PIN's runtime type
// (never its value).
fn main() {
    let pin: secret<i64> = 42;
    let kind = type(pin);
    if kind == "int" {
        print("pin format ok");
    } else {
        print("pin format bad");
    }
}

// A login session held as a map. A successful password check adds a token key; the audit line
// prints the user name, which is in the map from the start either way.
fn main() {
    let stored: secret<i64> = 42;
    let guess = 7;
    let mut session = {"user": "ana", "role": "guest"};
    if guess == stored {
        session["token"] = "t-1";
    }
    print("audit: session for " + session["user"]);
    print("role: " + session.role);
}

// Composable transforms: `then(f, g)` chains two stages. The billing pipeline mixes in a secret
// salt (its result is only range-checked). The display pipeline reads the public offset of a
// settings record that also holds an API key; its result is printed.
struct Settings {
    offset: i64,
    api_key: secret<i64>,
}

fn then(f, g) {
    return |x| g(f(x));
}

fn main() {
    let salt: secret<i64> = 42;
    let cfg = Settings { offset: 7, api_key: salt + 1 };
    let salted = then(then(then(then(|x| x + salt, |x| x * 2), |x| x + 1), |x| x % 1000), |x| x - 3);
    let h = salted(5);
    assert(h > -1000000);
    let shown = then(then(then(then(|x| x + cfg.offset, |x| x * 2), |x| x + 1), |x| x % 1000), |x| x - 3);
    print(shown(5));
}

// Timesheets: each row is an employee name followed by the hours logged per day. Hours are
// confidential; the summary line shows the name and how many days were logged.
fn summary(row) {
    return row[0] + ": " + str(len(row) - 1) + " days";
}

fn main() {
    let h: secret<i64> = 42;
